At this point I've collected so many high refresh rate-related fixes that I'll probably bundle them all into a plugin if this one turns out not to have any unforeseen problems. But for now do feel free to try this:
JavaScript:
SceneManager.updateMain = function () {
    let newFrame = false;
    if (Utils.isMobileSafari()) {
        this.changeScene();
        this.updateScene();
        newFrame = true;
    } else {
        var newTime = this._getTimeInMsWithoutMobileSafari();
        var fTime = (newTime - this._currentTime) / 1000;
        if (fTime > 0.25) fTime = 0.25;
        this._currentTime = newTime;
        this._accumulator += fTime;
        while (this._accumulator >= this._deltaTime) {
            newFrame = true;
            this.updateInputData();
            this.changeScene();
            this.updateScene();
            this._accumulator -= this._deltaTime;
        }
    }
    if(newFrame) this.renderScene();
    this.requestUpdate();
};
It would actually be quite useful to hear from a bunch of people with different games and systems on whether this breaks anything.
